 "content": "def transform(grid):
    # Translate each non-background connected component horizontally toward the
    # right, using the corresponding row's nearest available alignment. 8s are
    # fixed guide markers; other colors are independently shifted rightward.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 8 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color,comp))
    # Each item is shifted as far right as possible without overlapping any
    # other colored component or fixed guide marker.
    occupied={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    for color,comp in sorted(comps, key=lambda z:max(x for _,x in z[1]), reverse=True):
        for y,x in comp: out[y][x]=0
    for color,comp in sorted(comps, key=lambda z:max(x for _,x in z[1]), reverse=True):
        shift=0
        while True:
            nxt=shift+1
            if any(x+nxt>=w or (y,x+nxt) in occupied for y,x in comp): break
            shift=nxt
        for y,x in comp:
            out[y][x+shift]=color; occupied.add((y,x+shift))
    return out
